import {api,el,loadAssets,statusLabels,statusIcons,signout} from './display-api.mjs';
import {createPicker,setupRename} from './display-picker.mjs';
const $=s=>document.querySelector(s),scene=$('#rockScene'),orbit=$('#rockOrbit'),params=new URLSearchParams(location.search),demo=params.get('demo')==='1';
let state,catalog,assets,position=0,target=0,frame=0,grid=false,busy=false,pointer=null,lastDrag=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),mod=(v,n)=>((v%n)+n)%n;
function itemAt(index){const id=state.order[mod(index,state.order.length)];return state.items.find(i=>i.id===id)}
function art(item){return assets[item.productId]?.src||catalog.get(item.productId)?.img||''}
function render(){if(!state)return;const n=state.order.length;$('#rockEmpty').hidden=n>0;$('#rockSelected').hidden=!n;$('.orbit-controls').hidden=!n||grid;$('#prevRock').disabled=n<2;$('#nextRock').disabled=n<2;
 if(!n){orbit.replaceChildren();$('#rockCounter').textContent='';return}
 const selected=mod(Math.round(position),n),current=itemAt(selected),p=catalog.get(current.productId);$('#rockCounter').textContent=(selected+1)+' / '+n;$('#selectedName').textContent=p?.name||'Edge Sculpture';$('#selectedStatus').textContent=statusIcons[current.status]+' '+statusLabels[current.status];$('#selectedProduct').href='https://edgesculpture.es/products/'+encodeURIComponent(current.productId);$('#removeRock').hidden=demo;
 const count=Math.min(9,n),base=Math.round(position),radius=Math.min(scene.clientWidth*.31,325),width=Math.min(230,scene.clientWidth*.39);
 const keys=new Set();for(let k=-Math.floor(count/2);k<Math.ceil(count/2);k++){
  const index=base+k,item=itemAt(index),key=item.id;keys.add(key);let node=[...orbit.children].find(n=>n.dataset.id===key);
  if(!node){node=el('button',undefined,'floating-slot');node.type='button';node.dataset.id=key;node.tabIndex=-1;const rock=new Image();rock.src='/assets/floating-rock-v1.webp';rock.alt='';rock.className='rock-art';const shadow=el('span',undefined,'rock-contact'),piece=new Image();piece.src=art(item);piece.alt='';piece.draggable=false;piece.className='rock-piece';const status=el('span',statusIcons[item.status],'rock-piece-status '+item.status);node.append(rock,shadow,piece,status);orbit.append(node);node.onclick=()=>{if(performance.now()-lastDrag<250)return;const delta=mod(state.order.indexOf(key)-Math.round(target)+n/2,n)-n/2;rotate(Math.round(target)+delta)};}
  node.setAttribute('aria-label',(catalog.get(item.productId)?.name||'Piece')+' · '+statusLabels[item.status]);
  const angle=(index-position)*Math.PI*2/count,depth=(Math.cos(angle)+1)/2,scale=.52+.48*depth,x=Math.sin(angle)*radius,y=(depth-.5)*100;
  node.style.width=width+'px';node.style.height=(width*1.55)+'px';node.style.transform=`translate(-50%,-50%) translate(${x}px,${y}px) scale(${scale})`;node.style.opacity=.22+.78*depth;node.style.zIndex=String(Math.round(depth*100));node.style.filter='saturate('+(.45+.55*depth)+')';node.dataset.selected=String(mod(index,n)===selected);
 }for(const node of [...orbit.children])if(!keys.has(node.dataset.id))node.remove();
}
function animate(){frame=0;const delta=target-position;position=Math.abs(delta)<.002?target:position+delta*.16;render();if(position!==target&&!document.hidden)frame=requestAnimationFrame(animate)}
function rotate(value){if(!state?.order.length)return;target=value;if(reduced.matches){position=target;render()}else if(!frame)frame=requestAnimationFrame(animate)}
$('#prevRock').onclick=()=>rotate(Math.round(target)-1);$('#nextRock').onclick=()=>rotate(Math.round(target)+1);
scene.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();rotate(Math.round(target)+(e.key==='ArrowLeft'?-1:1))}});
let lastWheel=0;scene.addEventListener('wheel',e=>{if(document.activeElement!==scene||!state?.order.length)return;e.preventDefault();if(performance.now()-lastWheel>200){lastWheel=performance.now();rotate(Math.round(target)+(Math.abs(e.deltaX)>Math.abs(e.deltaY)?Math.sign(e.deltaX):Math.sign(e.deltaY))) }},{passive:false});
scene.addEventListener('pointerdown',e=>{if(!state?.order.length)return;scene.focus({preventScroll:true});pointer={id:e.pointerId,x:e.clientX,y:e.clientY,start:position,moved:false};scene.setPointerCapture(e.pointerId)});
scene.addEventListener('pointermove',e=>{if(!pointer||e.pointerId!==pointer.id)return;const dx=e.clientX-pointer.x;if(Math.abs(dx)>8)pointer.moved=true;if(pointer.moved){cancelAnimationFrame(frame);frame=0;target=position=pointer.start-dx/130;render()}});
function release(e){if(!pointer||e.pointerId!==pointer.id)return;if(pointer.moved)lastDrag=performance.now();pointer=null;rotate(Math.round(target))}scene.addEventListener('pointerup',release);scene.addEventListener('pointercancel',release);
new ResizeObserver(()=>render()).observe(scene);document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(frame);frame=0;if(!document.hidden&&target!==position)rotate(target)});
function renderGrid(){const root=$('#rockGrid');root.replaceChildren();for(const id of state.order){const item=state.items.find(i=>i.id===id),card=el('button',undefined,'rock-grid-card'),img=new Image();img.src=art(item);img.alt='';img.loading='lazy';card.append(img,el('span',catalog.get(item.productId)?.name||'Piece'),el('small',statusIcons[item.status]+' '+statusLabels[item.status]));card.onclick=()=>{grid=false;$('#toggleGrid').textContent='Grid view';$('#toggleGrid').setAttribute('aria-pressed','false');root.hidden=true;scene.hidden=false;position=target=state.order.indexOf(id);render();scene.focus()};root.append(card)}}
$('#toggleGrid').onclick=()=>{grid=!grid;$('#toggleGrid').textContent=grid?'Orbit view':'Grid view';$('#toggleGrid').setAttribute('aria-pressed',String(grid));scene.hidden=grid;$('#rockGrid').hidden=!grid;if(grid)renderGrid();render()};
function applyState(next){state=next;$('#displayTitle').textContent=state.name;document.title=state.name+' · Edge Shelf';position=target=state.order.length?mod(Math.round(position),state.order.length):0;render();if(grid)renderGrid()}
const context={getState:()=>state,beforeMutate:async()=>{if(busy)throw Error('Please wait for this change to save.');},applyState,focusPiece:id=>{position=target=state.order.indexOf(id);render()}};
$('#removeRock').onclick=async()=>{if(busy)return;busy=true;$('#removeRock').disabled=true;try{applyState(await api('displays',{method:'POST',body:JSON.stringify({action:'remove',displayId:state.layoutId,revision:state.revision,itemId:itemAt(Math.round(position)).id})}));$('#rockStatus').textContent='Removed from this display. Your collection is unchanged.'}catch(e){$('#rockStatus').textContent=e.message}finally{busy=false;$('#removeRock').disabled=false}};
async function start(){({catalog,assets}=await loadAssets());if(demo){const choices=[...catalog.values()].filter(p=>/^(Panda Cub|Dragon - Red|Tiger Cub - Bengal|Bear Cub|Horse Bust - Bay|Owl - Golden|Fox Bust|Elephant Calf)$/.test(p.name)).slice(0,8);const items=choices.map((p,i)=>({id:'demo-'+i,productId:p.id,status:['current','previous','wishlist'][i%3]}));state={name:'Edge Rocks · Demo',items,order:items.map(i=>i.id)};$('#rockStatus').textContent='Demo collection — these pieces are not added to your account.';applyState(state)}else{const id=params.get('id');if(!id){location.replace('/');return}const data=await api('bootstrap?display='+encodeURIComponent(id));if(data.state.type!=='rocks'){location.replace('/display.html?id='+data.state.layoutId);return}applyState(data.state);$('#adminMenuLink').hidden=!data.profile.isAdmin;signout();const picker=createPicker(context);$('#addPiece').hidden=false;$('#addPiece').onclick=()=>picker.open();setupRename(context)}
 const menu=$('#shelfNavigation'),toggle=$('#menuToggle');toggle.onclick=()=>{menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden))};document.addEventListener('click',e=>{if(!menu.contains(e.target)&&!toggle.contains(e.target)){menu.hidden=true;toggle.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.hidden=true;toggle.setAttribute('aria-expanded','false')}});
}
start().catch(e=>{$('#rockStatus').textContent=e.message;if(e.status===401){const link=el('a','Sign in to Edge Shelf');link.href='/api/auth/login';$('#rockStatus').append(link)}});
